// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this)); // owner
        vm.assume(actor.code.length == 0); // plain recipient succeeds on transfer
        amount = bound(amount, 1, address(c).balance == 0 ? 0 : type(uint256).max);
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint128).max);

        // fund the contract
        vm.deal(address(this), amount);
        (bool s,) = payable(address(c)).call{value: amount}("");
        assertTrue(s);

        vm.deal(actor, 0);
        uint256 before = actor.balance;

        vm.prank(actor);
        c.withdraw(amount);

        // RULE: the caller of withdraw receives exactly the withdrawn amount.
        assertTrue(actor.balance - before == amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test() public {
        require(address(this) != c.owner());
        // fund the contract so a successful withdrawAll would change its balance
        require(address(this).balance >= 1 ether);
        c.deposit{value: 1 ether}();

        uint balBefore = address(c).balance;
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector));
        require(!ok);
        assert(address(c).balance == balBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function test(uint256 amount, uint256 wval) public {
        require(amount > 0);
        require(address(this).balance >= amount);
        require(c.owner() != address(this));

        c.receive{value: amount}();
        uint256 balBefore = address(c).balance;
        require(balBefore >= wval);

        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdraw.selector, wval));
        assert(!ok && address(c).balance == balBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint seed) public payable {
        require(true);
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // The test contract was not the deployer/owner of c, so any withdrawAll
        // attempt by it must be blocked by the onlyOwner check, for any seed/value.
        assert(reverted || msg.sender == address(this));
    }
    receive() external payable {}
}

