    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient");
        if (amount > 0) {
            c.withdrawAll{value: amount} == address(0);
        }
        address caller = msg.sender;
        address ownerAddr = c.owner();
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assert(caller == ownerAddr ? (!reverted || ownerAddr == address(0)) : reverted);
    }
    receive() external payable {}
